   "id": "term_tied_to_unspecified_msa",
   "severity": "medium",
   "message": "The DPA's term depends on a 'main services agreement' that is not identified, so its duration and end date cannot be determined from this document.",
   "quote": "This DPA is coterminous with the main services agreement between the Parties."
  },
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "The DPA has no liability clause, so liability for a data breach is not capped or allocated here. Exposure would depend on the unidentified main services agreement or on default law.",
   "quote": "EXCEPT AS EXPRESSLY SET OUT IN THIS AGREEMENT, NEITHER PARTY MAKES ANY OTHER WARRANTY, EXPRESS OR IMPLIED, INCLUDING ANY WARRANTY OF MERCHANTABILITY OR FITNESS FOR A PARTICULAR PURPOSE."
  },
  {
   "id": "thin_security_obligations",
   "severity": "medium",
   "message": "Security measures are described only as 'appropriate', with no specific standards. This is vague for a Controller relying on the Processor to protect Personal Data.",
   "quote": "Processor shall implement appropriate technical and organisational measures to protect Personal Data."
  },
  {
   "id": "delaware_law_with_eu_processor",
   "severity": "low",
   "message": "Delaware law governs a DPA with a German processor. GDPR-required terms, such as cross-border transfer mechanisms and data subject assistance, are not addressed.",
   "quote": "This Agreement shall be governed by and construed in accordance with the laws of the State of Delaware, without regard to its conflict of laws principles."
  },
  {
   "id": "reciprocal_audit_limited",
   "severity": "low",
   "message": "Audit rights are limited to once per year and cover records only. This may be too narrow for Northwind to verify the Processor's data protection compliance.",
   "quote": "a Party may audit the other Party's records solely to verify compliance with this Agreement"
  }
